xml.Script:
        Colors[0] := '009600'; // Green
        Colors[1] := 'FFFF00'; // Yellow
        Colors[2] := 'FF800A'; // Orange
        Colors[3] := 'C80000'; // Red
        Colors[4] := '990099'; // Violett
        Colors[5] := '1C34C3'; // Blue
        Colors[6] := '222222'; // Black

        R := 0.6;
        D := R * 0.65;
        H := R * 0.25;

        for i := 0 to 5 do begin
            ax[i] := cos( Pi / 3 * i);
            ay[i] := sin( Pi / 3 * i);
        end;

        N := 48;
        M := N/12;
        for i := 0 to N - 1 do begin
            x[i] := R * cos(2 * Pi / N * i);
            y[i] := R * sin(2 * Pi / N * i);
        end;

        function FromTo(iFrom, iTo);
        begin
            Result := IntToStr(iFrom);
            for j := iFrom + 1 to iTo do
                Result := Result + ';' + IntToStr(j);
            for j := iFrom - 1 downto iTo do
                Result := Result + ';' + IntToStr(j);
        end;

Macro.Script:
i1 := i mod N;
i2 := (i + 1) mod N;
Inc(i);
